/* Simplified drawings of common UK road signs for the Signs tab. Meanings follow the Highway Code and the Traffic Signs Manual. */
(function(){
const R='#d4151b',BL='#0a58b3',AM='#f5a300';
const ring=i=>`<circle cx="50" cy="50" r="45" fill="#fff" stroke="${R}" stroke-width="9"/>${i}`;
const blue=i=>`<circle cx="50" cy="50" r="47" fill="${BL}"/>${i}`;
const tri=i=>`<polygon points="50,8 93,85 7,85" fill="#fff" stroke="${R}" stroke-width="8" stroke-linejoin="round"/>${i}`;
const box=i=>`<rect x="6" y="6" width="88" height="88" rx="8" fill="#111"/>${i}`;
const t=(s,x,y,z,f='#111')=>`<text x="${x}" y="${y}" font-family="Arial,Helvetica,sans-serif" font-weight="700" font-size="${z}" text-anchor="middle" fill="${f}">${s}</text>`;
const lorry=(x,y,s,c='#111')=>`<g transform="translate(${x} ${y}) scale(${s})" fill="${c}"><rect width="30" height="16" rx="1"/><path d="M32 4h9l5 6v6H32z"/><circle cx="9" cy="18" r="3.6"/><circle cx="38" cy="18" r="3.6"/></g>`;
const car=(x,y,s,c='#111')=>`<g transform="translate(${x} ${y}) scale(${s})" fill="${c}"><path d="M2 12l4-8h16l5 8h5v6H0v-6z"/><circle cx="8" cy="18" r="3.4"/><circle cx="25" cy="18" r="3.4"/></g>`;
const arrowUp='<path d="M50 18L74 46H59V82H41V46H26Z" fill="#fff"/>';
const S=[];
const add=(g,n,s,m,h)=>S.push({g,n,s,m,h:h||''});

/* Orders */
add('Orders','Stop',`<polygon points="31,4 69,4 96,31 96,69 69,96 31,96 4,69 4,31" fill="${R}" stroke="#fff" stroke-width="3"/>${t('STOP',50,60,26,'#fff')}`,'You must stop at the line, then give way to traffic on the major road before you go on.','Stop even if the road looks clear. Check your mirrors and the trailer swing before pulling out.');
add('Orders','Give Way',`<polygon points="7,14 93,14 50,92" fill="#fff" stroke="${R}" stroke-width="8" stroke-linejoin="round"/>${t('GIVE WAY',50,38,12)}`,'Give way to traffic on the major road. Be ready to stop at the line.','A long vehicle needs a bigger gap to pull out. Wait for it.');
add('Orders','No Entry',`<circle cx="50" cy="50" r="47" fill="${R}"/><rect x="17" y="41" width="66" height="18" fill="#fff"/>`,'No vehicles may enter. It is usually the exit of a one way street.','Do not follow a satnav down a no entry road. Plan the route for a vehicle your size.');
add('Orders','No Vehicles',ring(''),'No vehicles of any kind are allowed through. Pedal cycles being pushed are allowed.','');
add('Orders','No Overtaking',ring(`${car(14,40,.8)}${car(54,40,.8,R)}`),'You must not overtake the vehicle in front. It applies from the sign until the end sign.','');
add('Orders','No Overtaking by Goods Vehicles',ring(`${lorry(13,38,.52)}${car(52,40,.8,R)}`),'Goods vehicles over the weight shown on the sign, or over 7.5 tonnes if none is shown, must not overtake.','Check the plate under the sign for the weight and for times.');
add('Orders','Speed Limit',ring(t('50',50,64,40)),'The maximum speed in mph. It applies until you pass a different limit sign or the national speed limit sign.','Always use the limit for your vehicle type if it is lower than the sign.');
add('Orders','National Speed Limit',`<circle cx="50" cy="50" r="46" fill="#fff" stroke="#111" stroke-width="4"/><line x1="24" y1="76" x2="76" y2="24" stroke="#111" stroke-width="9"/>`,'The national speed limit applies.','Goods vehicle up to 7.5 tonnes: 50 mph on single carriageways, 60 on dual carriageways and 70 on motorways. Goods vehicle over 7.5 tonnes: 50, 60 and 60. Vehicles towing a trailer have their own limits.');
add('Orders','No Stopping (Clearway)',`<circle cx="50" cy="50" r="45" fill="${BL}" stroke="${R}" stroke-width="8"/><path d="M29 29L71 71M71 29L29 71" stroke="${R}" stroke-width="10"/>`,'You must not stop on the carriageway or verge, even to load or unload, except in an emergency or if traffic forces you to.','A red cross on blue means no stopping at all.');
add('Orders','No Waiting',`<circle cx="50" cy="50" r="45" fill="${BL}" stroke="${R}" stroke-width="8"/><path d="M27 73L73 27" stroke="${R}" stroke-width="10"/>`,'You must not wait here at the times on the plate. Loading and unloading may be allowed, so read the plate.','');

/* Mandatory */
add('Mandatory','Ahead Only',blue(arrowUp),'You must go straight on. A blue circle gives an order.','');
add('Mandatory','Turn Left',blue('<path d="M18 50L44 26V40H80V60H44V74Z" fill="#fff"/>'),'You must turn left ahead.','');
add('Mandatory','Keep Left',blue(`<g transform="rotate(-135 50 50)">${arrowUp}</g>`),'Pass the sign on the left side.','');
add('Mandatory','Minimum Speed',blue(t('30',50,63,38,'#fff')),'You must drive at the speed shown or faster, unless it is unsafe.','');

/* Warning */
add('Warning','Low Bridge',tri('<path d="M30 78V60a20 20 0 0 1 40 0v18" fill="none" stroke="#111" stroke-width="7"/>'),'A low bridge ahead. The plate or a nearby sign shows the headroom in feet and metres.','Check the height of your vehicle and load against the sign. Use the height marker in the cab. If you are too tall, find another route before you reach the bridge. Bridge strikes cost lives and a lot of money.');
add('Warning','Crosswinds',tri(`<path d="M30 74V36" stroke="#111" stroke-width="5"/><path d="M32 38h38l-8 9 8 9H32z" fill="#111"/>`),'You may meet strong side winds, for example on a bridge or an open road.','High sided and empty vehicles are hit hardest. Slow down, keep a firm grip and expect gusts when you pass gaps or leave shelter.');
add('Warning','Steep Hill Downwards',tri(`<path d="M24 56L76 76H24Z" fill="#111"/>${t('10%',60,52,17)}`),'A steep downhill ahead. The figure shows the gradient.','Select a low gear before the top and use the retarder or exhaust brake. Riding the brakes can make them fade.');
add('Warning','Steep Hill Upwards',tri(`<path d="M24 76L76 56V76Z" fill="#111"/>${t('10%',38,52,17)}`),'A steep uphill ahead. The figure shows the gradient.','Change down early and keep the engine in its power band. Leave a bigger gap to the vehicle in front.');
add('Warning','Road Narrows',tri('<path d="M34 78Q46 63 46 53Q46 41 34 31M66 78Q54 63 54 53Q54 41 66 31" fill="none" stroke="#111" stroke-width="6"/>'),'The road narrows ahead on both sides. Be ready to give way or to slow down.','');
add('Warning','Slippery Road',tri(`${car(34,42,.75)}<path d="M28 78q6-7 11 0t11 0t11 0t11 0" fill="none" stroke="#111" stroke-width="4"/>`),'The road surface may be slippery. Slow down and brake gently.','');
add('Warning','Traffic Signals Ahead',tri(`<rect x="40" y="29" width="20" height="50" rx="5" fill="#111"/><circle cx="50" cy="40" r="6" fill="#e53935"/><circle cx="50" cy="54" r="6" fill="${AM}"/><circle cx="50" cy="68" r="6" fill="#2e9e4f"/>`),'Traffic lights ahead. Be ready to stop.','');
add('Warning','Crossroads',tri('<rect x="46" y="30" width="8" height="48" fill="#111"/><rect x="26" y="50" width="48" height="8" fill="#111"/>'),'A crossroads ahead. Look for traffic from both sides.','');
add('Warning','T Junction',tri('<rect x="26" y="36" width="48" height="8" fill="#111"/><rect x="46" y="36" width="8" height="42" fill="#111"/>'),'A T junction ahead. The road you are on ends.','');
add('Warning','Roundabout',tri(`<circle cx="50" cy="58" r="14" fill="none" stroke="#111" stroke-width="5"/><path d="M50 36l-6 9h12zM69 62l-10-2 8-6zM32 62l10-2-8-6z" fill="#111"/>`),'A roundabout ahead. Give way to traffic from the right unless signs say otherwise.','Keep the trailer in lane. On a large roundabout use the left lane and swing wide only if it is safe to do so.');
add('Warning','Level Crossing with Barrier',tri('<rect x="26" y="40" width="5" height="38" fill="#111"/><rect x="69" y="40" width="5" height="38" fill="#111"/><rect x="26" y="46" width="48" height="9" fill="#111"/><path d="M38 46v9M50 46v9M62 46v9" stroke="#fff" stroke-width="3"/>'),'A level crossing with a gate or barrier ahead. Stop when the lights flash or the barrier lowers.','Never stop on the crossing. Make sure there is room for the whole vehicle on the far side. If it is long, low or slow, use the telephone at a user worked crossing and follow the notice.');
add('Warning','Queues Likely',tri(`${car(30,38,.6)}${car(30,56,.6)}`),'Traffic is likely to queue ahead. Slow down early.','Do not rely on the traffic ahead being able to stop quickly. Leave extra room and use your hazards for a queue at speed.');
add('Warning','Other Danger',tri(t('!',50,76,54)),'There is a danger that is not covered by another sign. The plate underneath tells you what.','');

/* Lorry limits */
add('Lorry Limits','Weight Limit',ring(t('7.5t',50,62,28)),'No vehicles over this maximum gross weight. The limit is the vehicle weight shown on its plate, not what it carries.','If your plated weight is over the limit you cannot use the road, even if you are empty. Plates under the sign may allow access for loading.');
add('Lorry Limits','Goods Vehicles Over Weight',ring(`${lorry(27,28,.9)}${t('7.5t',50,74,22)}`),'No goods vehicles over the maximum gross weight shown. A plate may add except for loading or access.','Plan the whole route before you leave and read the plate. A delivery inside a weight limit zone may be allowed, but only for the loading or unloading the plate permits.');
add('Lorry Limits','Height Limit',ring(`<path d="M34 22v56M27 30l7-8 7 8M27 70l7 8 7-8" fill="none" stroke="#111" stroke-width="4"/>${t('4.5m',66,57,17)}`),'No vehicles taller than the height shown.','Measure from the road to the highest point, including a fridge unit, aerials or roof equipment. Set the cab height marker for every load and trailer.');
add('Lorry Limits','Width Limit',ring(`<path d="M24 40v30M76 40v30" stroke="#111" stroke-width="5"/><path d="M30 55h40M38 47l-8 8 8 8M62 47l8 8-8 8" fill="none" stroke="#111" stroke-width="4"/>${t('2.0m',50,34,16)}`),'No vehicles wider than the width shown.','Remember mirrors and loads that overhang the body.');
add('Lorry Limits','Length Limit',ring(`${lorry(18,26,.7)}<path d="M18 54h64M26 47l-8 7 8 7M74 47l8 7-8 7" fill="none" stroke="#111" stroke-width="4"/>${t('10m',50,76,16)}`),'No vehicles longer than the length shown. The distance is written on the sign or on a plate.','An artic or a lorry with a drawbar trailer counts its full length.');

/* Motorway */
add('Motorway','Red Cross Lane Signal',box(`<path d="M24 24L76 76M76 24L24 76" stroke="${R}" stroke-width="12"/>`),'Do not use this lane. It is closed. Move to another lane in good time.','If you pass under a red cross on a smart motorway you can be fined and get points.');
add('Motorway','Move Left or Lane Closed Ahead',box(`<g transform="rotate(-135 50 50)"><path d="M50 18L74 46H59V82H41V46H26Z" fill="${AM}"/></g>`),'Move to the lane the arrow points to. A lane is closed ahead.','Start moving over early. A heavy vehicle needs time to merge safely.');
add('Motorway','Variable Speed Limit',box(`<circle cx="50" cy="50" r="34" fill="#fff" stroke="${R}" stroke-width="8"/>${t('50',50,62,30)}`),'A mandatory speed limit set for the conditions. It applies to the lane under the sign.','A limit with a red ring is the law and is often enforced by cameras.');
add('Motorway','Flashing Amber Lights',box(`<circle cx="32" cy="50" r="14" fill="${AM}"/><circle cx="68" cy="50" r="14" fill="${AM}"/>`),'There is a hazard ahead. Slow down and be ready to stop. Look for the message on the sign.','');
/* Roadworks */
const rw=i=>`<rect x="6" y="6" width="88" height="88" rx="8" fill="${AM}" stroke="#111" stroke-width="4"/>${i}`;
add('Roadworks','Road Works',tri(`<circle cx="46" cy="40" r="5" fill="#111"/><path d="M44 46l-8 16 6 2 6-12 6 10 5-3-8-13z M30 70h30l-6-8z" fill="#111"/>`),'Road works ahead. Expect workers, narrowed lanes, cones and slower traffic.','Slow down early and be ready to stop. Workers may be close to your wing mirrors.');
add('Roadworks','Lane Closed Ahead',rw(`<g fill="#111"><rect x="30" y="20" width="10" height="60"/><rect x="60" y="20" width="10" height="60"/></g><path d="M50 78V44M38 54l12-14 12 14" stroke="#111" stroke-width="7" fill="none"/>`),'A lane is closed ahead for works. Merge in good time to the lane that stays open.','Let a gap open and merge early. Do not push in at the last moment.');
add('Roadworks','Temporary Speed Limit',`<circle cx="50" cy="50" r="45" fill="#fff" stroke="${R}" stroke-width="9"/>${t('40',50,63,36)}`,'A mandatory speed limit through the works. It stays in force until you see the end of the limit.','Roadworks limits are often enforced by average speed cameras. Your HGV limit still applies if it is lower.');
add('Roadworks','Road Narrows',tri(`<path d="M34 78V50l12-26M66 78V50L54 24" stroke="#111" stroke-width="8" fill="none"/>`),'The road gets narrower ahead on both sides.','Check your width against any width limit and give way where signs say so.');
/* Direction */
const rc=(bg,bd,i)=>`<rect x="4" y="22" width="92" height="56" rx="6" fill="${bg}" stroke="${bd}" stroke-width="4"/>${i}`;
add('Direction','Motorway Direction Sign',rc(BL,'#fff',t('M1',50,60,26,'#fff')),'Blue background with white text: the route is a motorway, or leads onto one.','Motorways have their own rules, including no stopping on the hard shoulder except in an emergency.');
add('Direction','Primary Route Sign',rc('#0b7a3b','#fff',t('A1',50,60,26,'#fff')),'Green background with white text: a primary route, the main A roads between large towns.','');
add('Direction','Local Route Sign',rc('#fff','#111',t('Town',50,60,22,'#111')),'White background with black text and border: a non-primary or local route.','');
add('Direction','Tourist Sign',rc('#7a4a1b','#fff',t('Castle',50,60,20,'#fff')),'Brown background: a tourist attraction or tourist route.','Check the height and weight limits before following signs to an attraction.');
/* Information */
add('Information','Parking',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${BL}"/>${t('P',50,72,64,'#fff')}`,'A place where you may park. Read any plates for times, tickets and who the parking is for.','Check that the bay suits your vehicle length and weight.');
add('Information','Hospital',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${BL}"/><rect x="20" y="20" width="60" height="60" fill="#fff"/><path d="M50 28v44M28 50h44" stroke="${BL}" stroke-width="12"/>`,'The way to a hospital, or the hospital itself. Take care for ambulances and pedestrians.','');
add('Information','Lane Direction Signs',rc(BL,'#fff','<path d="M34 70V36M34 36l-8 10M34 36l8 10M66 70V36M66 36l-8 10M66 36l8 10" stroke="#fff" stroke-width="5" fill="none"/>'),'Arrows on a blue panel show which lanes go where. Get in the right lane in good time.','Use your mirrors and signal early so other traffic can see a long vehicle changing lane.');
/* ---- Extra signs (Highway Code traffic signs section) ---- */
const K='#111',W='#fff',GR='#0b7a3b',BR='#7a4a1b',GY='#8a929b';
const slash=`<line x1="22" y1="22" x2="78" y2="78" stroke="${R}" stroke-width="8"/>`;
const bent=(dir)=>`<g transform="${dir==='l'?'translate(100 0) scale(-1 1)':''}"><path d="M40 78V46H60M52 34l14 12-14 12" stroke="${K}" stroke-width="8" fill="none" stroke-linejoin="round"/></g>`;
const lane=(x,c='#fff')=>`<rect x="${x}" y="14" width="2.5" height="72" fill="${c}" opacity=".7"/>`;
/* Orders: red circle */
add('Orders','No Right Turn',ring(bent('r')+slash),'You must not turn right here.','Plan your route so you are not forced to find a place to turn a long vehicle round.');
add('Orders','No Left Turn',ring(bent('l')+slash),'You must not turn left here.','');
add('Orders','No U-Turns',ring(`<path d="M36 78V44a14 14 0 0 1 28 0v10M54 46l10 12 10-12" stroke="${K}" stroke-width="8" fill="none" stroke-linejoin="round"/>`+slash),'You must not make a U-turn.','');
add('Orders','Entry to 20 mph Zone',ring(t('20',50,63,34)+''),'Entry to a 20 mph zone. The limit applies to every road in the zone until you see the end sign.','Zones usually have humps or other calming. Take them slowly so the load and your suspension are not thrown about.');
add('Orders','No Motor Vehicles',ring(`${car(18,38,.85)}<path d="M62 30l8 8M70 30l-8 8" stroke="${K}" stroke-width="3"/>`+slash),'No motor vehicles are allowed.','');
add('Orders','No Vehicles Carrying Explosives',ring(`<circle cx="50" cy="56" r="14" fill="${K}"/><path d="M50 42l8-14M44 30l6 2M60 34l6-4M56 28l4-6" stroke="${AM}" stroke-width="4" stroke-linecap="round"/>`),'No vehicle carrying explosives may enter.','Applies to explosives loads. Follow any other dangerous goods restrictions, such as tunnel limits, set out on your paperwork.');
add('Orders','No Towed Caravans',ring(`<rect x="22" y="40" width="40" height="22" rx="5" fill="${K}"/><path d="M62 54h14" stroke="${K}" stroke-width="4"/>`+slash),'No vehicles towing a caravan.','');
add('Orders','Give Priority to Oncoming Traffic',`<circle cx="50" cy="50" r="45" fill="#fff" stroke="${R}" stroke-width="9"/><path d="M38 78V22M38 22l-9 14M38 22l9 14" stroke="${R}" stroke-width="8" fill="none"/><path d="M62 22v56M62 78l-9-14M62 78l9-14" stroke="${K}" stroke-width="8" fill="none"/>`,'Give way to traffic coming the other way. It is usually a narrow section or an obstruction on your side. The red arrow is your direction.','Stop and wait in good time if the oncoming driver is already in the gap. Do not force a long vehicle in.');
add('Orders','School Crossing Patrol Stop Sign',ring(`<rect x="40" y="26" width="20" height="30" fill="${R}"/><rect x="47" y="56" width="6" height="26" fill="${K}"/>${t('STOP',50,46,10,W)}`),'A school crossing patrol is on duty. Stop when the patrol steps into the road and holds up the sign.','Stay stopped until the patrol and children have reached the pavement and the sign is lowered.');
add('Orders','Manual STOP and GO Board',`<circle cx="50" cy="50" r="46" fill="${R}"/>${t('STOP',50,59,24,W)}`,'Temporary signs held by a road worker at roadworks. STOP means stop at the line. GO means you may proceed when it is safe.','They may be single lane working. Wait for the GO board and watch for oncoming traffic.');
add('Orders','Parking Permit Holders Only',ring(`<rect x="24" y="30" width="52" height="40" fill="${BL}"/>${t('P',50,62,32,W)}`),'Parking is only for people with a permit for the zone.','Do not leave the vehicle here without a permit for the zone. Check the plates for times and exceptions.');
/* Mandatory: blue circle and rectangle */
add('Mandatory','Turn Right',blue('<path d="M30 78V44h32M48 28l16 16-16 16" stroke="#fff" stroke-width="10" fill="none" stroke-linejoin="round"/>'),'You must turn right.','');
add('Mandatory','Keep Right',`<g transform="translate(100 0) scale(-1 1)">${S.find(x=>x.n==='Keep Left').s}</g>`,'Keep to the right of the sign.','');
add('Mandatory','Pass Either Side',blue('<path d="M50 80V50M50 50L32 28M50 50L68 28" stroke="#fff" stroke-width="9" fill="none"/>'),'Vehicles may pass on either side of the sign to reach the same destination.','');
add('Mandatory','One Way',`<rect x="4" y="24" width="92" height="52" rx="4" fill="${BL}"/><path d="M18 50h58M62 34l18 16-18 16" stroke="#fff" stroke-width="10" fill="none"/>`,'Traffic can only go one way. It is the direction the arrow points.','');
add('Mandatory','Mini Roundabout',blue('<path d="M34 50a16 16 0 1 1 6 12" stroke="#fff" stroke-width="7" fill="none"/><path d="M28 56l8 8 8-10" stroke="#fff" stroke-width="7" fill="none"/>'),'A mini-roundabout. Give way to traffic from the immediate right.','You may have to drive over the central dome with a long vehicle. Check there is nobody close to your nearside before you do.');
add('Mandatory','Buses and Cycles Only',blue(`<rect x="22" y="30" width="38" height="26" rx="4" fill="#fff"/><circle cx="32" cy="62" r="5" fill="#fff"/><circle cx="52" cy="62" r="5" fill="#fff"/>`),'The lane is only for buses and pedal cycles. Check the plate for other vehicles, such as taxis.','Do not enter a bus lane in an HGV unless a plate allows it.');
/* Warning triangles */
const wt=i=>tri(i);
add('Warning','Bend to Right',wt('<path d="M40 78V56q0-14 18-24M50 28l12 6-6 12" stroke="#111" stroke-width="7" fill="none"/>'),'A bend to the right ahead. The sign is reversed for a bend to the left.','Slow down before the bend and keep the load stable. Your trailer cuts the corner shorter than you think, so keep it off the kerb.');
add('Warning','Double Bend',wt('<path d="M34 78V60q0-12 14-14t14-12" stroke="#111" stroke-width="7" fill="none"/>'),'A double bend. The first bend is to the left in this picture. The sign is reversed if it starts to the right.','');
add('Warning','Hump Bridge',wt('<path d="M24 74q26-36 52 0" stroke="#111" stroke-width="7" fill="none"/>'),'A hump bridge ahead. You may not see over the top.','Long vehicles can ground out on the crest. Slow down and use the lane position the sign layout suggests.');
add('Warning','Uneven Road',wt('<path d="M20 72h14q4-12 10 0t12 0t14 0" stroke="#111" stroke-width="7" fill="none"/>'),'The road surface is uneven ahead.','Check the load is secure. Reduce speed to stop the vehicle bouncing.');
add('Warning','Risk of Ice',wt(`${t('ICE',50,70,24)}`),'The road may be icy ahead. The plate may give a distance.','Increase your gap, use gentle braking and slow before any bend.');
add('Warning','Soft Verges',wt(`<path d="M20 72h60" stroke="#111" stroke-width="6"/><path d="M60 72l10-20 10 20" fill="#111"/>`),'The verge is soft. Do not pull onto it.','A heavy vehicle can sink or tip if it moves onto soft ground.');
add('Warning','Falling Rocks',wt(`<circle cx="42" cy="46" r="7" fill="#111"/><circle cx="60" cy="58" r="6" fill="#111"/><path d="M26 76h46" stroke="#111" stroke-width="5"/>`),'Rocks may fall or have fallen onto the road.','Watch the road surface for debris, and do not stop under an overhang.');
add('Warning','Pedestrians in Road Ahead',wt(`<circle cx="46" cy="36" r="5" fill="#111"/><path d="M44 42l-4 20h18l-4-20z M40 62l-4 14M58 62l4 14" stroke="#111" stroke-width="5" fill="#111"/>`),'Pedestrians may be walking in the road ahead.','Give them space and keep a low speed. Your mirrors have blind spots, so check them often.');
add('Warning','Zebra Crossing Ahead',wt(`<path d="M24 74h52" stroke="#111" stroke-width="3"/><path d="M26 78l8-8M40 78l8-8M54 78l8-8M68 78l8-8" stroke="#111" stroke-width="4"/><circle cx="50" cy="38" r="5" fill="#111"/><path d="M50 44v16M50 52l-8 6M50 52l8 6" stroke="#111" stroke-width="5"/>`),'There is a zebra crossing ahead.','Give way once a pedestrian has stepped onto the crossing. Never overtake in the approach zone.');
add('Warning','Level Crossing without Barrier',wt(`<path d="M30 76l40-44M30 32l40 44" stroke="#111" stroke-width="7"/>`),'A level crossing with no barrier or gate. The crossing is open to trains at any time.','Stop at the red lights. Never stop on a crossing, and do not drive onto it unless your whole vehicle can clear it.');
add('Warning','Opening or Swing Bridge',wt(`<path d="M22 72h22M56 72h22M44 72l10-18" stroke="#111" stroke-width="6"/>`),'An opening or swing bridge ahead. It may be closed to road traffic while it opens.','Obey the flashing red lights and the barrier. Do not cross while lights are flashing.');
add('Warning','Tunnel Ahead',wt(`<path d="M28 76V54q0-18 22-18t22 18v22" stroke="#111" stroke-width="7" fill="none"/>`),'A tunnel ahead.','Check the height and dangerous goods restrictions at the entry, and turn your lights on. Do not stop inside.');
add('Warning','Overhead Electric Cable',wt(`<path d="M30 40l12 20l12-20l12 20" stroke="#111" stroke-width="5" fill="none"/><path d="M50 26v-8" stroke="#111" stroke-width="5"/>${t('4.5m',50,78,12)}`),'Overhead electric cable. The plate gives the maximum safe vehicle height beneath it.','Tipper bodies and cranes can touch cables even when raised only slightly. Lower the body before you move.');
add('Warning','Risk of Grounding',wt(`<path d="M24 66h20l8-8l24 8" stroke="#111" stroke-width="6" fill="none"/>${lorry(30,40,.6)}`),'Low-slung vehicles may ground on a hump or ramp.','Think of your ground clearance with low loaders, tanker frames and fitted underrun bars.');
add('Warning','Traffic Merging from Left',wt(`<path d="M50 78V30M32 72q4-20 18-30" stroke="#111" stroke-width="7" fill="none"/>`),'Traffic joins from the left ahead.','Let a gap open, and look for vehicles coming up in your mirrors.');
add('Warning','Dual Carriageway Ends',wt(`<path d="M38 78V50l12-16M62 78V50L50 34M62 50V34" stroke="#111" stroke-width="7" fill="none"/>`),'The dual carriageway ends. Expect two-way traffic ahead.','Take care when overtaking.');
add('Warning','Two-way Traffic Ahead',wt(`<path d="M38 70V34M38 34l-8 12M38 34l8 12" stroke="${K}" stroke-width="7" fill="none"/><path d="M62 34v36M62 70l-8-12M62 70l8-12" stroke="#777" stroke-width="7" fill="none"/>`),'The road goes from one way to two-way ahead.','');
add('Warning','Cattle',wt(`<path d="M28 60h36l4-12h6M36 60v14M60 60v14M66 48l4-10" stroke="#111" stroke-width="6" fill="none"/><rect x="30" y="46" width="30" height="14" fill="#111"/>`),'Cattle may be on the road.','Slow down and drive quietly.');
add('Warning','Wild Animals',wt(`<path d="M30 70l8-22 8 6 8-6 8 22M46 54l-4-14 8 6" stroke="#111" stroke-width="6" fill="#111"/>`),'Wild animals such as deer may be on the road.','They are often active at dawn and dusk.');
add('Warning','Horse Riders',wt(`<path d="M28 62h34l6-18 8-4M36 62v14M58 62v14" stroke="#111" stroke-width="6" fill="none"/><rect x="34" y="48" width="26" height="14" fill="#111"/>`),'Horses or ponies may be on the road. Slow down and give them a wide berth.','Pass slowly and with plenty of room. Do not sound the horn or rev the engine.');
add('Warning','Tram Crossing',wt(`<rect x="28" y="40" width="44" height="26" rx="4" fill="#111"/><path d="M36 40V30M64 40V30M30 30h40" stroke="#111" stroke-width="4"/>`),'Trams cross the road ahead.','Trams cannot swerve. Never stop on the track.');
add('Warning','Low-flying Aircraft',wt(`<path d="M24 54h52M50 38v34M40 62h20" stroke="#111" stroke-width="6" fill="none"/>`),'Low-flying aircraft or sudden aircraft noise.','');
add('Warning','Distance to Give Way',tri(t('GIVE WAY',50,58,10)+'<text x="50" y="72" font-family="Arial" font-size="10" text-anchor="middle" fill="#111">150 yds</text>'),'A give way line is the distance shown ahead.','');
add('Warning','Road Humps',tri(`<path d="M22 70q10-18 20 0q10-18 20 0" stroke="#111" stroke-width="7" fill="none"/>`),'Road humps ahead. The plate may show how far they run.','Go over them slowly and at an angle that your axle can cope with.');
/* Lorry limits (niche) */
add('Lorry Limits','No Lorries (HGV Ban)',ring(`${lorry(16,40,.9)}`+slash),'No goods vehicles above a given weight are allowed. A plate may say "except for loading".','Know your gross weight. Signs may show times, so check a plate. Following a sat nav not made for HGVs can send you down banned roads.');
add('Lorry Limits','Low Bridge Height Plate',`<rect x="6" y="26" width="88" height="48" rx="4" fill="#fff" stroke="#111" stroke-width="4"/>${t('13\'6"',50,59,22)}`,'A plate showing the maximum height of the bridge or structure. It is usually in feet and inches and in metres.','Know your vehicle height every time, including with a roof box, sleeper or aerial. Never gamble on a low bridge. Bridge strikes put lives at risk and cost a lot.');
add('Lorry Limits','Advisory Route for Lorries',`<rect x="4" y="22" width="92" height="56" rx="6" fill="${BL}" stroke="#fff" stroke-width="3"/>${lorry(22,38,.9,'#fff')}<path d="M26 62h50" stroke="#fff" stroke-width="3"/>`,'A recommended route for lorries. It can be a better option than the main road for heavy vehicles.','Follow it unless your delivery point is elsewhere. It avoids low bridges and narrow streets.');
add('Lorry Limits','Climbing Lane',`<rect x="4" y="22" width="92" height="56" rx="6" fill="${BL}" stroke="#fff" stroke-width="3"/><path d="M20 62l20-14 18 6 20-18" stroke="#fff" stroke-width="5" fill="none"/>${lorry(30,34,.5,'#fff')}`,'An extra lane for slow vehicles on a long uphill climb. Sign designs vary, so read the wording.','Use it when you cannot keep up with the traffic. It lets faster vehicles get by.');
add('Lorry Limits','Escape Lane',`<rect x="4" y="22" width="92" height="56" rx="6" fill="${BL}" stroke="#fff" stroke-width="3"/><path d="M26 74V36l26 12v26" stroke="#fff" stroke-width="5" fill="none"/>`,'A lane at the bottom of a steep hill for vehicles that have lost their brakes. Escape lanes are signed locally, and the design of the sign varies.','Keep out of it and never park in it. If your brakes are failing, use it. It is safer than hitting a bend at speed.');
/* Motorway */
const gantry=(i)=>`<rect x="6" y="6" width="88" height="88" rx="8" fill="#111"/>${i}`;
add('Motorway','Red X Lane Closed',gantry(`<path d="M28 28l44 44M72 28L28 72" stroke="${R}" stroke-width="12"/>`),'A red X over a lane. You must not drive in the lane.','A red X applies to the lane below it only. Move into an open lane in good time and do not return to a closed lane. On a smart motorway a red X over the hard shoulder means do not use it.');
add('Motorway','Red Flashing Lights',gantry(`<circle cx="30" cy="50" r="13" fill="${R}"/><circle cx="70" cy="50" r="13" fill="${R}"/>`),'Red flashing lights above a lane. The lane is closed. You must not drive in it.','A lane closed by flashing red lights can have people or vehicles in it. Do not go into it.');
add('Motorway','Advisory Speed Limit',gantry(`<circle cx="50" cy="50" r="32" fill="#fff"/>${t('40',50,62,28)}`),'An advisory speed limit with no red ring. It is not a legal limit, so it cannot be enforced like one.','You should still follow it. It is usually set for queues or an incident ahead, and driving too fast for the conditions can still be charged as careless driving.');
add('Motorway','Mandatory Speed Limit (Ring)',gantry(`<circle cx="50" cy="50" r="32" fill="#fff" stroke="${R}" stroke-width="8"/>${t('60',50,62,28)}`),'A mandatory speed limit with a red ring. It is the law and can be enforced, even if the number is lower than the normal road limit, such as 50 on a 70 road.','Your HGV limit still applies if it is lower than the sign.');
add('Motorway','End of Restriction',gantry(`<circle cx="50" cy="50" r="32" fill="#fff" stroke="#111" stroke-width="3"/><path d="M26 74L74 26" stroke="#111" stroke-width="5"/>`+`<text x="50" y="40" font-family="Arial" font-weight="700" font-size="12" text-anchor="middle" fill="#111">END</text>`),'The earlier restriction no longer applies.','');
add('Motorway','National Speed Limit Signal',gantry(`<circle cx="50" cy="50" r="32" fill="#fff" stroke="#111" stroke-width="3"/><path d="M26 74L74 26" stroke="#111" stroke-width="7"/>`),'The national speed limit applies again.','Your limit for your type of vehicle and road applies.');
add('Motorway','Lane Closed Ahead (Merge Left)',gantry(`<path d="M30 78V50l22-26" stroke="${AM}" stroke-width="10" fill="none"/><path d="M40 28l14-6 6 14" stroke="${AM}" stroke-width="8" fill="none"/>`),'A lane is closed further ahead. Move over in the direction of the arrow.','Merge early and keep a safe gap. Do not use up all of the lane before merging.');
add('Motorway','Lane Control Green Arrow',gantry(`<path d="M50 76V28M50 76l-16-20M50 76l16-20" stroke="#2ecc71" stroke-width="10" fill="none" transform="rotate(180 50 50)"/>`),'A green arrow over a lane means the lane is open.','Used where lanes are opened and closed.');
add('Motorway','Lane Control Move Over',gantry(`<path d="M34 76L66 34M66 34H46M66 34v20" stroke="#fff" stroke-width="10" fill="none"/>`),'A white diagonal arrow. Change lanes in the direction shown.','Signal early and move over in good time.');
add('Motorway','Fog or Reduced Visibility',gantry(`<path d="M24 38h52M24 52h52M24 66h52" stroke="#fff" stroke-width="7"/>`),'Fog or reduced visibility ahead.','Check your lights, reduce your speed, and increase your gap.');
add('Motorway','Hard Shoulder Open as a Lane',gantry(`<circle cx="50" cy="50" r="32" fill="#fff" stroke="${R}" stroke-width="8"/>${t('60',50,62,26)}`),'On a smart motorway, a speed limit over the hard shoulder means you can use it as a running lane.','If the hard shoulder shows a red X or is blank, it is for emergency use only.');
add('Motorway','Emergency Area',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${BL}"/><rect x="26" y="22" width="48" height="56" fill="#f58220"/>${t('SOS',50,58,20,W)}`,'A refuge area for use in an emergency only, shown by an SOS sign. They are set at intervals along smart motorways.','Pull in and leave the vehicle by the nearside door where it is safe. Use the roadside phone to call for help and move behind the barrier.');
add('Motorway','Countdown Markers',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${BL}"/><path d="M24 78l52-52" stroke="#fff" stroke-width="6"/><path d="M28 70l10-10M40 58l10-10M52 46l10-10" stroke="${R}" stroke-width="4"/>`,'Markers before a motorway exit. Each bar is 100 yards to the exit.','Be in the correct lane by the 3-bar marker.');
add('Motorway','Motorway Service Area',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${BL}"/>${t('Services',50,52,16,W)}<path d="M26 72h48" stroke="#fff" stroke-width="3"/>`,'A motorway service area ahead. The sign shows the name and what is there, and the distance to it.','Check fuel and hours when you see the first sign, since the next stop may be far.');
add('Motorway','Start of Motorway',`<rect x="6" y="22" width="88" height="56" rx="6" fill="${BL}" stroke="#fff" stroke-width="3"/><path d="M26 66h48M36 66l8-24h12l8 24" stroke="#fff" stroke-width="4" fill="none"/>`,'Motorway rules apply from here. No stopping except in an emergency, and certain vehicles are not allowed.','');
add('Motorway','End of Motorway',`<rect x="6" y="22" width="88" height="56" rx="6" fill="${BL}" stroke="#fff" stroke-width="3"/><path d="M26 66h48M36 66l8-24h12l8 24" stroke="#fff" stroke-width="4" fill="none"/><path d="M20 30L80 70" stroke="${R}" stroke-width="6"/>`,'The motorway ends. Normal road rules and limits apply, so check the speed limit.','');
add('Motorway','Lorries Keep Out of Right Lane',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${BL}"/>${lane(34)}${lane(64)}${lorry(36,38,.7,'#fff')}<circle cx="78" cy="62" r="10" fill="none" stroke="${R}" stroke-width="3"/>`,'Vehicles towing, and goods vehicles over 7.5 tonnes, must not use the right-hand lane of a motorway with three or more lanes. Rule 265.','Stay in the left two lanes.');
add('Motorway','Slip Road Priority',`<rect x="6" y="22" width="88" height="56" rx="6" fill="${BL}" stroke="#fff" stroke-width="3"/><path d="M30 70V32M50 70V32M70 70V40l-12-8" stroke="#fff" stroke-width="5" fill="none"/>`,'A sign showing which lane has priority at a slip road. The main carriageway traffic normally has priority.','Look for lane gains and drops, and be ready to give way or move over.');
add('Motorway','Contraflow Crossover',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${AM}" stroke="#111" stroke-width="4"/><path d="M30 78V50l24-24M70 78V40" stroke="#111" stroke-width="8" fill="none"/>`,'One lane crossover at contraflow roadworks. Traffic is moved across to the opposite carriageway.','Narrow lanes: stay central and keep your distance. Do not overtake.');
/* Roadworks extra */
add('Roadworks','Road Works One Mile Ahead',`<rect x="6" y="22" width="88" height="56" rx="6" fill="${AM}" stroke="#111" stroke-width="4"/>${t('1 mile',50,58,24)}`,'Road works start in about a mile.','Slow down before the works and check for lane closures.');
add('Roadworks','Loose Chippings',tri(`<circle cx="34" cy="62" r="4" fill="#111"/><circle cx="48" cy="52" r="4" fill="#111"/><circle cx="60" cy="66" r="4" fill="#111"/><circle cx="68" cy="54" r="4" fill="#111"/>`),'Loose chippings on the road. They can be thrown up by your tyres.','Keep a low speed and extra gap. Flying stones can chip other drivers\' windscreens and paint.');
add('Roadworks','Temporary Hazard',tri(t('!',50,70,40)),'A temporary hazard at the roadworks. The plate says what it is.','');
add('Roadworks','Lane Restrictions Ahead',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${AM}" stroke="#111" stroke-width="4"/><path d="M30 76V24M50 76V24M70 76V24" stroke="#111" stroke-width="3"/><rect x="44" y="30" width="12" height="40" fill="#111"/>`,'Lanes are restricted ahead at the road works. Check the lanes on the sign.','');
add('Roadworks','End of Road Works',`<rect x="6" y="22" width="88" height="56" rx="6" fill="${AM}" stroke="#111" stroke-width="4"/>${t('END',50,58,24)}`,'The end of the roadworks and any temporary restrictions, including speed limits.','Restrictions stay in place until you see the end sign. Do not speed up early.');
add('Roadworks','Slow-moving Works Vehicle Blocking a Lane',`<rect x="6" y="6" width="88" height="88" rx="8" fill="${AM}" stroke="#111" stroke-width="4"/>${lorry(28,26,.8)}<path d="M68 76L40 52M50 48H36v18" stroke="#111" stroke-width="6" fill="none"/>`,'A slow-moving or stationary works vehicle blocks a lane. Pass in the direction of the arrow.','Do not pass on the wrong side of the arrow. Keep clear of workers on foot.');
/* Signals */
add('Signals','Red Traffic Light',`<rect x="30" y="8" width="40" height="84" rx="10" fill="#222"/><circle cx="50" cy="26" r="10" fill="${R}"/><circle cx="50" cy="50" r="10" fill="#444"/><circle cx="50" cy="74" r="10" fill="#444"/>`,'Stop. Wait behind the stop line.','Make sure the whole of your vehicle is behind the line, including the cab and any mirrors.');
add('Signals','Red and Amber',`<rect x="30" y="8" width="40" height="84" rx="10" fill="#222"/><circle cx="50" cy="26" r="10" fill="${R}"/><circle cx="50" cy="50" r="10" fill="${AM}"/><circle cx="50" cy="74" r="10" fill="#444"/>`,'Stop. Do not go until the green light shows.','');
add('Signals','Green',`<rect x="30" y="8" width="40" height="84" rx="10" fill="#222"/><circle cx="50" cy="26" r="10" fill="#444"/><circle cx="50" cy="50" r="10" fill="#444"/><circle cx="50" cy="74" r="10" fill="#2ecc71"/>`,'Go if the way is clear. Take care when turning, and give way to pedestrians crossing.','Make sure the junction is clear to the far side before you enter. A long vehicle can get stuck across a junction.');
add('Signals','Amber',`<rect x="30" y="8" width="40" height="84" rx="10" fill="#222"/><circle cx="50" cy="26" r="10" fill="#444"/><circle cx="50" cy="50" r="10" fill="${AM}"/><circle cx="50" cy="74" r="10" fill="#444"/>`,'Stop at the stop line. Only go on if you have crossed the line when it came on, or are too close to stop safely.','A loaded HGV needs a long distance to stop. If it is safe, stop.');
add('Signals','Green Arrow',`<rect x="30" y="8" width="40" height="84" rx="10" fill="#222"/><path d="M62 72H40M52 62l-12 10 12 10" stroke="#2ecc71" stroke-width="5" fill="none" transform="rotate(180 50 72)"/><circle cx="50" cy="26" r="9" fill="#444"/><circle cx="50" cy="48" r="9" fill="#444"/>`,'You can go in the direction of the arrow, even if other lights are on. Only go if the way is clear.','');
add('Signals','Flashing Red (Level Crossing)',`<rect x="26" y="10" width="48" height="80" rx="8" fill="#222"/><circle cx="50" cy="32" r="12" fill="${R}"/><circle cx="50" cy="68" r="12" fill="${R}" opacity=".5"/>`,'Alternate flashing red lights mean stop. You will see them at level crossings, lifting bridges, airfields and fire stations.','Stop at the line. Do not drive on to a level crossing when the lights are flashing, or if there is a queue that would leave you on the track.');
/* Road markings */
const rd=(i)=>`<rect x="4" y="4" width="92" height="92" rx="6" fill="#444"/>${i}`;
add('Markings','Double White Lines',rd(`<path d="M46 8v84M54 8v84" stroke="#fff" stroke-width="3"/>`),'Do not cross or straddle the line if the solid line is nearer to you. You may cross if the line nearest to you is broken, to overtake, if safe.','Take care on bends and hills. A long vehicle that takes a turn wide can cross the line.');
add('Markings','Hazard Warning Line',rd(`<path d="M50 8v12M50 28v12M50 48v12M50 68v12M50 88v4" stroke="#fff" stroke-width="3"/>`),'A long line with short gaps warns of a hazard ahead. Keep to your side.','Do not overtake unless you can see the whole way and it is safe.');
add('Markings','Box Junction',rd(`<rect x="20" y="20" width="60" height="60" stroke="#f5c400" stroke-width="3" fill="none"/><path d="M20 20L80 80M80 20L20 80" stroke="#f5c400" stroke-width="3"/>`),'Do not enter the yellow box unless your exit is clear. You may wait in it to turn right if only oncoming traffic stops you.','A long HGV can end up blocking the box. Wait until you know there is room for the whole length of your vehicle.');
add('Markings','Single Yellow Line',rd(`<path d="M10 56h80" stroke="#f5c400" stroke-width="6"/>`),'Waiting is restricted at the times shown on nearby signs. Check them.','');
add('Markings','Double Yellow Lines',rd(`<path d="M10 50h80M10 62h80" stroke="#f5c400" stroke-width="5"/>`),'No waiting at any time unless a sign says otherwise.','Loading and unloading is usually allowed unless there are kerb marks, but you cannot wait to do it.');
add('Markings','Red Route Lines',rd(`<path d="M10 56h80" stroke="${R}" stroke-width="7"/>`),'A red route. You must not stop on the line. A single red line has times shown on signs, a double red line means no stopping at any time.','In London and some cities, penalty charges apply quickly. Check the signs for any loading bays.');
add('Markings','Yellow Kerb Marks',rd(`<path d="M10 70h80" stroke="#888" stroke-width="10"/><path d="M26 62v12M46 62v12M66 62v12M86 62v12" stroke="#f5c400" stroke-width="5"/>`),'Short yellow lines on the kerb. Loading and unloading is not allowed at the times shown on the plate. A single mark restricts at certain times.','Always read the plate. You may not be able to load here.');
add('Markings','Loading Bay',rd(`<rect x="14" y="22" width="72" height="56" stroke="#fff" stroke-width="3" fill="none"/>${t('LOADING',50,56,12,'#fff')}`),'Reserved for loading and unloading. It may be limited to goods vehicles and certain times.','You can only stop to load or unload. Do not park here.');
add('Markings','Stop Line',rd(`<path d="M10 40h80" stroke="#fff" stroke-width="8"/>`),'Stop behind the line at traffic lights, a stop sign or police control.','Position the front of the vehicle behind it, including at junctions with a cab overhang.');
add('Markings','Give Way Line',rd(`<path d="M10 40h10M30 40h10M50 40h10M70 40h10" stroke="#fff" stroke-width="6"/>`),'A broken line across the road at a junction. Give way to traffic on the major road.','');
add('Markings','Hatched Area (Chevrons)',rd(`<path d="M30 80L50 20L70 80M30 62L50 10L70 62" stroke="#fff" stroke-width="3" fill="none"/>`),'Chevron hatching with a solid edge line is a buffer. Do not enter it unless it is an emergency. Dashed edge lines mean you should avoid it if you can.','Look for a solid edge line. A solid line means do not enter the hatching unless it is an emergency.');
add('Markings','Bus Lane',rd(`<path d="M10 20h80M10 80h80" stroke="#fff" stroke-width="3"/>${t('BUS LANE',50,56,11,'#fff')}`),'A lane for buses, and sometimes cycles and taxis. The signs show the hours.','Do not drive in a bus lane when it is in force. Check the times.');
add('Markings','Cat\'s Eyes Colours',rd(`<circle cx="22" cy="50" r="8" fill="#fff"/><circle cx="42" cy="50" r="8" fill="${R}"/><circle cx="62" cy="50" r="8" fill="${AM}"/><circle cx="82" cy="50" r="8" fill="#2ecc71"/>`),'White marks lane lines or the centre. Red marks the left edge. Amber marks the right edge of a dual carriageway or motorway. Green marks side roads and slip roads.','At night you can tell where you are on a motorway by the colour of the studs next to you.');
add('Markings','Keep Clear',rd(`<rect x="12" y="18" width="76" height="64" stroke="#f5c400" stroke-width="3" fill="none"/>${t('KEEP',50,46,14,'#f5c400')}${t('CLEAR',50,66,14,'#f5c400')}`),'Do not stop or park in the area, even for a short time.','Do not stop in front of a school, fire station or ambulance entrance.');

add('Markings','Chevrons with Solid Border',rd(`<path d="M16 8V92M84 8V92" stroke="#fff" stroke-width="3"/><path d="M30 88L50 28L70 88M30 66L50 6L70 66" stroke="#fff" stroke-width="3" fill="none"/>`),'Chevron hatching with a solid white border. The Highway Code says you should not enter it, except in an emergency.','You may cross it if you are in an emergency. If you use it to get past and cause danger, you can be prosecuted for careless or dangerous driving.');
add('Markings','Chevrons with Broken Border',rd(`<path d="M16 8v12M16 28v12M16 48v12M16 68v12M84 8v12M84 28v12M84 48v12M84 68v12" stroke="#fff" stroke-width="3"/><path d="M30 88L50 28L70 88M30 66L50 6L70 66" stroke="#fff" stroke-width="3" fill="none"/>`),'Chevron hatching with a broken border. You should stay out of it unless you can see it is safe to enter.','Used to separate lanes or protect vehicles turning right, so enter only if it is clear and you need to.');
add('Markings','Double White Lines (Solid Line Nearest You)',rd(`<path d="M44 8v84" stroke="#fff" stroke-width="3"/><path d="M56 8v10M56 26v10M56 44v10M56 62v10M56 80v10" stroke="#fff" stroke-width="3"/><circle cx="30" cy="50" r="6" fill="#aaa"/>`),'You must not cross or straddle the line that is nearest to you. The broken line on the other side means the opposite driver may cross.','You can cross to get past a stationary vehicle, or a cycle, horse or road maintenance vehicle going 10 mph or less, if the road is clear. You can also cross to enter a side road or property.');
add('Markings','Solid White Edge Line',rd(`<path d="M16 8v84" stroke="#fff" stroke-width="4"/><path d="M50 8v12M50 28v12M50 48v12M50 68v12M50 88v4" stroke="#fff" stroke-width="3"/>`),'A solid white line along the edge of the carriageway marks the edge of the road. A hard shoulder is the area outside it.','Do not drive on or beyond the edge line, except in an emergency.');
add('Markings','Broken Lane Lines',rd(`<path d="M34 8v12M34 28v12M34 48v12M34 68v12M66 8v12M66 28v12M66 48v12M66 68v12" stroke="#fff" stroke-width="3"/>`),'Short broken white lines divide the lanes. You can change lanes when it is safe.','');
/* Vehicle markings */
const vm=(i)=>`<rect x="4" y="4" width="92" height="92" rx="6" fill="#eee" stroke="#999" stroke-width="2"/>${i}`;
add('Vehicle Markings','Rear Markers (Red and Yellow)',vm(`<rect x="12" y="38" width="76" height="24" fill="${R}"/><path d="M12 38l12 24M36 38l12 24M60 38l12 24" stroke="#f5e000" stroke-width="10"/>`),'Red and yellow rear markings help other drivers see a big, slow vehicle. They are required on motor vehicles over 7,500 kg and trailers over 3,500 kg.','Check them for dirt and damage every day. Make sure they are not covered or missing.');
add('Vehicle Markings','Projection Markers',vm(`<rect x="14" y="34" width="72" height="12" fill="#999"/><path d="M14 34L30 46M30 34L46 46M46 34l16 12M62 34l16 12" stroke="${R}" stroke-width="5"/>${t('+2m',50,76,16)}`),'Markers needed when a load or equipment, such as a crane jib, sticks out more than 2 m at the front or rear.','Mark long loads at both the sides and the ends. Use extra warning lamps in poor light.');
add('Vehicle Markings','Hazard Information Panel',vm(`<rect x="14" y="30" width="72" height="40" fill="#f58220" stroke="#111" stroke-width="3"/><path d="M14 50h72" stroke="#111" stroke-width="3"/>${t('33',50,46,14)}${t('1203',50,66,14)}`),'An orange panel with numbers on a tank vehicle. The top number is the hazard and the bottom number is the substance code. It lets the emergency services know what you are carrying.','Check the plates are right for your load and that they are visible from both sides and the rear.');
add('Vehicle Markings','Hazard Diamond',vm(`<polygon points="50,12 88,50 50,88 12,50" fill="${R}"/><path d="M50 30c-6 10-12 14-8 24 4 8 18 6 16-8 4 2 6 6 4 10" stroke="#fff" stroke-width="3" fill="#fff"/>`),'Diamond labels show the main danger of what you carry, such as flammable, toxic, corrosive or radioactive.','The same diamond must be on the packages. Your instructions in writing tell you what to do in an emergency.');
add('Vehicle Markings','School Bus Sign',vm(`<rect x="14" y="26" width="72" height="48" fill="#f5c400" stroke="#111" stroke-width="3"/><circle cx="36" cy="44" r="5" fill="#111"/><circle cx="52" cy="44" r="5" fill="#111"/><path d="M30 52v14M46 52v14M62 52v14M40 66h30" stroke="#111" stroke-width="4"/>`),'A school bus sign shows on the front or rear window of a bus or coach carrying children.','Expect children to cross near it. Slow down and take extra care passing.');
add('Vehicle Markings','Flashing Amber Beacon',vm(`<circle cx="50" cy="52" r="18" fill="${AM}"/><path d="M50 22v-6M26 30l-5-4M74 30l5-4M18 52h-8M82 52h8" stroke="${AM}" stroke-width="4"/>`),'An amber flashing beacon warns of a slow-moving or hazard vehicle, such as road maintenance, a recovery vehicle or an abnormal load.','Slow down, be ready to stop, and give it space. Never overtake close to it.');
add('Vehicle Markings','Blue Light Vehicle',vm(`<circle cx="50" cy="52" r="18" fill="${BL}"/><path d="M50 22v-6M26 30l-5-4M74 30l5-4M18 52h-8M82 52h8" stroke="${BL}" stroke-width="4"/>`),'Blue flashing lights mean an emergency vehicle: police, ambulance, fire or similar. They can be going through red lights.','Pull over and stop where it is safe. Do not brake suddenly or mount a kerb.');
add('Vehicle Markings','Green Beacon',vm(`<circle cx="50" cy="52" r="18" fill="#2ecc71"/><path d="M50 22v-6M26 30l-5-4M74 30l5-4M18 52h-8M82 52h8" stroke="#2ecc71" stroke-width="4"/>`),'A green flashing light shows a doctor on an emergency call, or a volunteer medical responder.','Give way where you safely can.');
/* Legal status for each sign */
const LAW=['Orders','Mandatory','Signals'],LN={
'Lorry Limits':{'Height Limit':'law','Width Limit':'law','Length Limit':'law','Weight Limit':'law','Goods Vehicles Over Weight':'law','No Lorries (HGV Ban)':'law','Low Bridge Height Plate':'info','Advisory Route for Lorries':'adv','Climbing Lane':'info','Escape Lane':'info'},
'Motorway':{'Red X Lane Closed':'law','Red Flashing Lights':'law','Advisory Speed Limit':'adv','Mandatory Speed Limit (Ring)':'law','Variable Speed Limit':'law','End of Restriction':'law','National Speed Limit Signal':'law','Hard Shoulder Open as a Lane':'law','Lorries Keep Out of Right Lane':'law','Red Cross Lane Signal':'law','Lane Control Green Arrow':'law','Lane Control Move Over':'law','Flashing Amber Lights':'warn','Move Left or Lane Closed Ahead':'warn','Lane Closed Ahead (Merge Left)':'warn','Fog or Reduced Visibility':'warn','Emergency Area':'info','Countdown Markers':'info','Motorway Service Area':'info','Start of Motorway':'law','End of Motorway':'info','Slip Road Priority':'info','Contraflow Crossover':'warn'},
'Roadworks':{'Temporary Speed Limit':'law','End of Road Works':'info','Slow-moving Works Vehicle Blocking a Lane':'law'},
'Markings':{'Hazard Warning Line':'sh','Chevrons with Solid Border':'sh','Chevrons with Broken Border':'sh','Hatched Area (Chevrons)':'sh','Cat\'s Eyes Colours':'info','Broken Lane Lines':'info','Solid White Edge Line':'law','Loading Bay':'law','Bus Lane':'law'},
'Vehicle Markings':{},'Direction':{},'Information':{}};
S.forEach(x=>{x.l=(LN[x.g]&&LN[x.g][x.n])||(LAW.includes(x.g)?'law':x.g==='Warning'?'warn':x.g==='Markings'?'law':x.g==='Vehicle Markings'?'veh':x.g==='Roadworks'?'warn':'info')});
window.SIGNS=S;
})();
